package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct { // 01 ORDER-REC, 15 bytes
	OrId    string          // PIC X(5) @0 len=5
	OrStat  string          // PIC X(1) @5 len=1
	OrQty   int64           // PIC 9(3) @6 len=3
	OrPrice decimal.Decimal // PIC 9(4)V99 @9 len=6
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var orderLines []string
var recPos int

// storeTruncate keeps only low-order digits that fit intDigits.V fracDigits
// and truncates fractional part toward zero.
func storeTruncate(val decimal.Decimal, intDigits, fracDigits int) decimal.Decimal {
	powFrac := decimal.New(1, int32(fracDigits))
	powTotal := decimal.New(1, int32(intDigits+fracDigits))
	scaled := val.Mul(powFrac).Truncate(0)
	isNeg := scaled.IsNegative()
	if isNeg {
		scaled = scaled.Abs()
	}
	var mod decimal.Decimal
	if intDigits+fracDigits > 0 {
		mod = scaled.Mod(powTotal)
	} else {
		mod = scaled
	}
	if isNeg {
		mod = mod.Neg()
	}
	return mod.Div(powFrac)
}

func formatEdited(val decimal.Decimal, picture string) string {
	parts := strings.Split(picture, ".")
	intPattern := parts[0]
	fracPattern := ""
	if len(parts) > 1 {
		fracPattern = parts[1]
	}
	intDigits := 0
	for _, c := range intPattern {
		if c == 'Z' || c == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, c := range fracPattern {
		if c == 'Z' || c == '9' {
			fracDigits++
		}
	}
	powFrac := decimal.New(1, int32(fracDigits))
	absVal := val.Abs()
	scaledInt := absVal.Mul(powFrac).Truncate(0)
	powTotal := decimal.New(1, int32(intDigits+fracDigits))
	var scaledMod decimal.Decimal
	if intDigits+fracDigits > 0 {
		scaledMod = scaledInt.Mod(powTotal)
	} else {
		scaledMod = scaledInt
	}
	intPart := scaledMod.Div(powFrac).Truncate(0)
	fracPart := scaledMod.Mod(powFrac)
	intVal := intPart.IntPart()
	fracVal := fracPart.IntPart()
	intDigitsStr := fmt.Sprintf("%0*d", intDigits, intVal)

	var intResult strings.Builder
	suppressed := true
	digitIdx := 0
	for _, ch := range intPattern {
		if ch == ',' {
			if suppressed {
				intResult.WriteRune(' ')
			} else {
				intResult.WriteRune(',')
			}
		} else if ch == 'Z' {
			d := intDigitsStr[digitIdx]
			digitIdx++
			if suppressed && d == '0' {
				intResult.WriteRune(' ')
			} else {
				intResult.WriteRune(rune(d))
				suppressed = false
			}
		} else if ch == '9' {
			d := intDigitsStr[digitIdx]
			digitIdx++
			intResult.WriteRune(rune(d))
			suppressed = false
		} else {
			intResult.WriteRune(ch)
		}
	}
	if fracDigits > 0 {
		fracDigitsStr := fmt.Sprintf("%0*d", fracDigits, fracVal)
		return intResult.String() + "." + fracDigitsStr
	}
	return intResult.String()
}

func loadLines() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			orderLines = []string{}
			return
		}
		fmt.Fprintf(os.Stderr, "error reading input.dat: %v\n", err)
		os.Exit(1)
	}
	if len(data) == 0 {
		orderLines = []string{}
		return
	}
	var lines []string
	start := 0
	for i := 0; i < len(data); i++ {
		if data[i] == '\n' {
			line := string(data[start:i])
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			lines = append(lines, line)
			start = i + 1
		}
	}
	if start < len(data) {
		line := string(data[start:])
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		lines = append(lines, line)
	}
	orderLines = lines
}

// paragraphs

func ReadPara() {
	if recPos >= len(orderLines) {
		WsEofFlag = "Y"
		return
	}
	line := orderLines[recPos]
	recPos++
	if len(line) < 15 {
		line += strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	orderRec.OrId = line[0:5]
	orderRec.OrStat = line[5:6]
	qtyStr := line[6:9]
	priceStr := line[9:15]

	// QTY 9(3)
	t := strings.TrimSpace(qtyStr)
	if t == "" {
		orderRec.OrQty = 0
	} else {
		clean := strings.ReplaceAll(qtyStr, " ", "")
		if clean == "" {
			orderRec.OrQty = 0
		} else {
			v, err := strconv.ParseInt(clean, 10, 64)
			if err != nil {
				v = 0
			}
			orderRec.OrQty = v
		}
	}
	// PRICE 9(4)V99
	cleanP := strings.ReplaceAll(priceStr, " ", "")
	if cleanP == "" {
		orderRec.OrPrice = decimal.NewFromInt(0)
	} else {
		// priceStr should be digits only
		v, err := strconv.ParseInt(cleanP, 10, 64)
		if err != nil {
			v = 0
		}
		orderRec.OrPrice = decimal.New(v, -2)
	}
	WsEofFlag = "N"
}

func ShowPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func ProcessPara() {
	WsTotal = decimal.NewFromInt(0)
	WsTotal = storeTruncate(WsTotal, 8, 2)
	if orderRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		prod := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		WsTotal = storeTruncate(prod, 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if orderRec.OrStat == "S" {
		rate := decimal.NewFromInt(105).Div(decimal.NewFromInt(100)) // 1.05
		prod := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(rate)
		rounded := prod.Round(2)
		WsTotal = storeTruncate(rounded, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if orderRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	sum := WsGrand.Add(WsTotal)
	WsGrand = storeTruncate(sum, 10, 2)
	ReadPara()
}

func SummaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	newStr := fmt.Sprintf("%02d", WsNewCount%100)
	shipStr := fmt.Sprintf("%02d", WsShipCount%100)
	cancelStr := fmt.Sprintf("%02d", WsCancelCount%100)
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", newStr, shipStr, cancelStr)
	invalidStr := fmt.Sprintf("%02d", WsInvalid%100)
	badQtyStr := fmt.Sprintf("%02d", WsBadQty%100)
	fmt.Printf("INVALID: %s BAD QTY: %s\n", invalidStr, badQtyStr)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func MainPara() {
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	loadLines()
	MainPara()
}
